/**
 * The `.shared/` protocol layout, resolved once per tool call.
 *
 * @module dwguard-dsh-hmos/paths
 */
/** Every path the workflow touches inside one workspace. */
export interface SharedPaths {
    /** Agent session working directory. */
    readonly workspace: string;
    /** `<workspace>/.shared` (or the configured directory). */
    readonly shared: string;
    readonly tasksDir: string;
    readonly artifactsDir: string;
    readonly knowledgeDir: string;
    readonly outboxDsh: string;
    readonly outboxDeveco: string;
    readonly stateFile: string;
    readonly specJson: string;
    readonly specMd: string;
    readonly briefMd: string;
    /** Brief for a CLI executor (`executor: cli`). */
    readonly cliBriefMd: string;
    readonly questionMd: string;
    readonly knowledgeIndex: string;
    /** Per-dimension audit progress, written as each audit sub-agent returns. */
    readonly auditProgress: string;
    /** Append-only gate calibration ledger (`knowledge/calibration.jsonl`). */
    readonly calibration: string;
    /** Aesthetic preference profile (`knowledge/aesthetic-profile.md`, table + JSON fence). */
    readonly aestheticProfileMd: string;
    /** Append-only aesthetic history (`knowledge/aesthetic-history.jsonl`). */
    readonly aestheticHistory: string;
    /** Visual baselines, one directory per task-pack version. */
    readonly visualBaselineDir: string;
    /** Latest baseline comparison (`artifacts/aesthetic/compare-latest.json`). */
    readonly aestheticCompare: string;
    /** Aesthetic artifacts directory (`artifacts/aesthetic`). */
    readonly aestheticDir: string;
    /** Design RAG library (0.6.2): cards, chunks, index and the generated CLI. */
    readonly designDir: string;
    readonly designManifest: string;
    readonly designChunks: string;
    readonly designIndex: string;
    readonly designFeedback: string;
    /** Dependency-free read-only query CLI generated by `library init`. */
    readonly designQueryScript: string;
    /** Design brief handed to DevEco (`tasks/design-brief.md`). */
    readonly designBriefMd: string;
    /** Suggestions from the last failed aesthetic audit (0.6.3 F). */
    readonly designReworkQueue: string;
    /** Recommended design options written for the user (0.6.8). */
    readonly designOptionsMd: string;
    /** Machine-readable recommendations consumed by capture-pack (0.6.8). */
    readonly designRecommendations: string;
    /** Local frozen design packs (0.6.8). */
    readonly designPacksLocalDir: string;
    /** Local pack registry / supersedes (0.7.0). */
    readonly designPacksIndex: string;
    /** Pack-level feedback log (0.7.0). */
    readonly designPackFeedback: string;
    /** Recommendation benchmark report (0.7.0). */
    readonly designRecommendBenchmarkMd: string;
    /** Embedding cache for hybrid rerank (0.6.4). */
    readonly designEmbeddings: string;
    /** Image feature cache for search-by-image (0.6.4). */
    readonly designImageFeatures: string;
    /** CLIP/multimodal embedding cache (0.6.5). */
    readonly designClipEmbeddings: string;
    readonly designRefsDir: string;
    readonly designInboxDir: string;
}
/**
 * Resolve the protocol layout for a workspace.
 * @param workspace - the agent session's cwd.
 * @param sharedDir - configured directory, relative (to the workspace) or absolute.
 */
export declare function resolvePaths(workspace: string, sharedDir: string): SharedPaths;
/**
 * Render a path for model-facing output: workspace-relative POSIX when inside
 * the workspace, absolute otherwise.
 */
export declare function displayPath(paths: SharedPaths, file: string): string;
